<script setup lang="ts">
import {ref,onUnmounted} from 'vue';import {useWallet} from '../stores/store';import {fmt} from '../data/mock';const w=useWallet();const mult=ref(1),running=ref(false),stake=ref(1000),msg=ref(''),hash=ref('');let iv:any;async function sha(s:string){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function start(){ if(stake.value>w.balance)return alert('balance'); w.add(-stake.value,'crash_stake'); const seed='demo-seed-'+Date.now(); hash.value=await sha(seed); running.value=true; mult.value=1; const crash=+(0.97/(1-Math.random())).toFixed(2); msg.value=`Provably Fair: server seed hash (committed) ${hash.value.slice(0,16)}... RTP 97%`; iv=setInterval(()=>{mult.value=+(mult.value*1.03).toFixed(2); if(mult.value>=Math.min(crash,100)){clearInterval(iv);running.value=false;msg.value+=` | Crashed @ ${mult.value}x — seed revealed: ${seed} (verify SHA-256(seed)=hash)`}},100)}
function cashout(){clearInterval(iv);running.value=false;const win=Math.floor(stake.value*mult.value);w.add(win,'crash_win');msg.value=`Cashed out ${fmt(win)} @ ${mult.value}x`};
</script>
<template><h2>Crash — Provably Fair (RTP 97%)</h2><div class="card"><h1 class="gold">{{mult.toFixed(2)}}x</h1><input type="number" v-model.number="stake"/><button v-if="!running" @click="start">Start Round</button><button v-else @click="cashout">Cash Out</button><p>{{msg}}</p><small>Verify: HMAC/hash committed before round, seed revealed after. Production API: /api/crash/* in apps/api.</small></div></template>
